from itertools import product

tat_ca_day = []


for do_dai in range(1, 11):

    for d in product("012", repeat=do_dai):


        if d[0] not in ('1', '2'):
            continue


        so_luong_2 = d.count('2')
        if so_luong_2 > do_dai / 2:

            gia_tri = int("".join(d))
            tat_ca_day.append(gia_tri)


tat_ca_day.sort()


t = int(input())  

for _ in range(t):
    n = int(input())   


    for i in range(n):
        print(tat_ca_day[i], end=" ")
    print()

