from itertools import product
a = []
b = ['0', '1', '2']
for length in range(1, 11):  
    for tup in product(b, repeat=length):
        s = ''.join(tup)
        if s[0] not in ('1', '2'):
            continue
        if s.count('2') * 2 <= len(s):
            continue
        a.append(int(s))
a.sort()
t = int(input())
for _ in range(t):
    n = int(input())
    print(*a[:n])
